using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace Dafeiyu.Tests
{
    public static class DraftConversationTests
    {
        static int passed,failed;static string root;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
        static void Run(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
        static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(root,i)))yield return x;}
        static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
        static PetWindow Pet(){var s=new PetSettings{AgentEnabled=false,ReadReplies=false,GreetingEnabled=false,AutoUpdate=false,OnboardingState="completed"};s.Text.BaseUrl="http://127.0.0.1:1";s.Text.Model="fixture";foreach(var key in s.Hotkeys.Keys.ToArray())s.Hotkeys[key]="";var p=new PetWindow(null,s,new SettingsStore(Path.Combine(root,Guid.NewGuid().ToString("N"),"settings.json")),null);typeof(PetWindow).GetField("workspaces",hidden).SetValue(p,new ConversationWorkspaceManager(p.Store.DirectoryPath,p.Skin.Id,()=>new Api(),()=>new Silent(),()=>null,()=>s,()=>true));return p;}
        static int Count(PetWindow p){return p.Projects.Projects.Sum(x=>x.Conversations.Count)+p.Projects.UnassignedConversations.Count+p.Projects.QuickConversations.Count;}
        static ChatWindow Chat(){return Application.Current.Windows.OfType<ChatWindow>().Single();}
        static void Send(ChatWindow chat){All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput").Text="draft input";All<Button>(chat).Single(b=>b.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<15;i++)Pump();}
        [STAThread]public static int Main(){root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"drafts-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Run("new conversation stays unlisted until first successful send",PendingDraft);Run("failed submission retains draft without adding a catalog entry",FailedSubmission);Run("project choice is pending until send and then persists under that project",ProjectChoice);Run("unassigned conversation appears in recent and can move into a project",Unassigned);Run("recent project visibility toggle persists without hiding unassigned chats",RecentFilter);app.Shutdown();Console.WriteLine("Draft conversation tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;}
        static void PendingDraft(){var p=Pet();try{int count=Count(p);p.NewActiveConversation();Pump();Check(Count(p)==count,"new conversation was saved before sending");var chat=Chat();Check(!All<Button>(chat).Any(b=>b.Name=="ConversationProjectPicker"),"ordinary chat exposed project selection");chat.Close();Pump();Check(Count(p)==count,"closing empty draft created a saved chat");}finally{p.Close();Pump();}}
        static void FailedSubmission(){var p=Pet();try{p.NewActiveConversation();Pump();int before=Count(p);p.Settings.Text.BaseUrl="invalid-url";var chat=Chat();var input=All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput");input.Text="retain this draft";All<Button>(chat).Single(b=>b.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Count(p)==before&&input.Text=="retain this draft","failed submission saved an empty conversation or lost the draft");}finally{foreach(var chat in Application.Current.Windows.OfType<ChatWindow>().ToArray())chat.Close();p.Close();Pump();}}
        static void ProjectChoice(){var p=Pet();try{var project=ProjectCatalogStore.CreateProject(p.Projects,"chosen",root);int count=project.Conversations.Count;p.NewProjectConversation(project);Pump();Check(project.Conversations.Count==count,"choosing a project eagerly saved an empty chat");Send(Chat());Check(project.Conversations.Count==count+1,"first send did not add chat to selected project");var saved=p.ProjectStore.Load();Check(saved.Projects.Single(x=>x.Id==project.Id).Conversations.Count==count+1,"project membership not persisted");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void Unassigned(){var p=Pet();try{p.Settings.AgentEnabled=true;var project=ProjectCatalogStore.CreateProject(p.Projects,"target",root);p.NewActiveConversation();Pump();Send(Chat());Check(p.Projects.UnassignedConversations.Count==1,"unassigned chat was not saved independently");var c=p.Projects.UnassignedConversations[0];Check(p.MoveConversation(ProjectCatalogStore.UnassignedProject(p.Projects,p.Settings),project,c),"moving unassigned chat failed");Check(!p.Projects.UnassignedConversations.Any()&&project.Conversations.Any(x=>x.Id==c.Id),"unassigned drag changed or lost chat identity");var workspace=p.Workspaces.OpenWorkspaces.Single(x=>x.Id==c.Id);Check(workspace.Session.History.Messages.Any(x=>x.Content=="draft input"),"move lost conversation history");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void RecentFilter(){var catalog=new ProjectCatalog();var project=ProjectCatalogStore.CreateProject(catalog,"project",root);catalog.UnassignedConversations.Add(new ConversationDefinition{Id="unassignedtest",Name="Loose"});var sidebar=new ProjectSidebar(new ProjectCatalogStore(Path.Combine(root,"recent.json")),catalog,delegate{},delegate{},delegate{},delegate{},delegate{});var toggle=All<Button>(sidebar).Single(b=>b.Name=="ToggleSection_recent");Check(toggle.ContextMenu!=null&&toggle.ContextMenu.Items.OfType<MenuItem>().Any(m=>m.Name=="NewSidebarSection"),"recent group omits section actions");toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!All<Button>(sidebar).Any(b=>b.Name.StartsWith("RecentConversation_")),"recent group did not collapse");All<Button>(sidebar).Single(b=>b.Name=="ToggleSection_recent").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(All<Button>(sidebar).Any(b=>b.Name=="RecentConversation_unassignedtest")&&All<Button>(sidebar).Any(b=>b.Name=="RecentConversation_"+project.Conversations[0].Id),"recent expansion lost shared work records");}
        sealed class Api:IConversationApi{public Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken t){return Task.FromResult("reply");}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken t){return Task.FromResult("");}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string text,CancellationToken t){return Task.FromResult(new byte[0]);}public void Dispose(){}}
        sealed class Silent:IReplySpeech{public Task SpeakAsync(string s,PetSettings p,CancellationToken t){return Task.FromResult(0);}public void Stop(){}public void SetVolume(int n){}public void Dispose(){}}
    }
}
